pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 firstVal, uint256 secondVal) public {
        vm.assume(firstVal != secondVal);

        c.Initialized();
        c.SetMinSum(firstVal);

        // The bug allows a second SetMinSum call (nonReentrant_ is a no-op) that changes MinSum.
        // Reference C would revert on a reentrant call, but we do not call from an attacking contract;
        // the bug is simply that the modifier does nothing, so a second call succeeds.
        // We try a second SetMinSum; if it succeeds, MinSum changes.
        bool ok;
        try c.SetMinSum(secondVal) { ok = true; } catch { ok = false; }

        // General rule: if SetMinSum succeeded (no revert), MinSum should be firstVal; otherwise MinSum is firstVal.
        // In the reference, the second call always reverts, so ok is false and MinSum == firstVal holds.
        // In the buggy version, the second call succeeds, so ok is true and MinSum becomes secondVal, breaking the rule.
        assertTrue(ok ? c.MinSum() == firstVal : c.MinSum() == firstVal);
    }
}

