pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 val1, uint256 val2) public {
        // Ensure we are in the admissible domain: the contract must be initialized
        // and the two values must be different so a mutation would be observable.
        vm.assume(val1 != val2);

        // Initialize the contract
        c.Initialized();

        // Reference: after initialization, SetMinSum must revert on every call (singleton write).
        // The bug makes a second call succeed and overwrite MinSum with val2.

        // First write (always succeeds)
        c.SetMinSum(val1);

        // Second write: under the reference this MUST revert; under the bug it succeeds.
        bool ok;
        try c.SetMinSum(val2) {
            ok = true;
        } catch {
            ok = false;
        }

        // If ok == true, the call succeeded (bug), MinSum was changed to val2,
        // which differs from the first set value val1.
        // If ok == false, the call reverted (reference), MinSum stays val1.
        // In either case, the invariant holds iff a successful second call does NOT change
        // MinSum away from val1.
        assertTrue(!ok || c.MinSum() == val1);
    }
}

