pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 val1, uint256 val2, address actor) public {
        vm.assume(val1 != val2);
        vm.assume(actor != address(0) && actor != address(this));

        // Deploy a reentrant attacker that will call SetMinSum(val2) during SetMinSum(val1)
        ReentrantAttacker attacker = new ReentrantAttacker(c, val1, val2);

        vm.prank(actor);
        bool ok;
        try c.SetMinSum(val1) { ok = true; } catch { ok = false; }
        // Reentrant call via the modifier hook is the key: attacker's receive() is triggered by
        // the low-level call in the fallback or other payable function. Since SetMinSum is non-payable,
        // we need to trigger reentrancy through another path. The bug is in the reentrancy guard;
        // we use a sequence where the attacker calls SetMinSum from a function that runs during the
        // original SetMinSum. We'll use the fallback: attacker calls a payable function that triggers
        // reentrancy. SetMinSum is not payable, so we use Put with _lockTime=0 and call reentrantly.
        // However, the invariant uses SetMinSum. We need to make the outer call to SetMinSum
        // and have the inner call also be SetMinSum. Since SetMinSum is non-payable, the reentrant
        // call cannot be triggered by a simple transfer. The attacker must make a direct call.
        // The broken guard allows reentrancy if another function with the same modifier calls SetMinSum.
        // We'll use a helper that performs a reentrant SetMinSum during the original SetMinSum.
        // The below sequence works because the attacker's code runs inside the modifier's body.
        // To achieve this, the attacker's function setMinSumReentrantly does: c.SetMinSum(val2) when called.
        // But the outer call is also SetMinSum. The guard is broken, allowing the reentrant call.

        // Actually simpler: we can directly have the attacker be the one initiating the outer call
        // and then performing a reentrant inner call. We deploy a contract that acts as the caller.

        // The final MinSum must equal the last argument passed to the outermost non-revert call.
        // Since the outer call is SetMinSum(val1), after completion MinSum should be val1.
        // The bug allows an inner reentrant SetMinSum(val2) to execute after the outer one,
        // leaving MinSum = val2.

        assertTrue(c.MinSum() == val1);
    }
}

contract ReentrantAttacker {
    C c;
    uint256 outerVal;
    uint256 innerVal;
    bool reentered;
    constructor(C _c, uint256 _outerVal, uint256 _innerVal) {
        c = _c;
        outerVal = _outerVal;
        innerVal = _innerVal;
    }
    fallback() external payable {
        if (!reentered) {
            reentered = true;
            c.SetMinSum(innerVal);
        }
    }
    function attack() external {
        c.SetMinSum(outerVal);
    }
}

