pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 v1, uint256 v2, address caller) public {
        // Ensure values are distinct so overwrite is observable, and keep them within reasonable bounds.
        vm.assume(v1 != v2);
        vm.assume(v1 > 0 && v2 > 0);
        // Deploy a re-entrant attacker.
        ReentrantAttacker attacker = new ReentrantAttacker(c, v2);
        // vm.deal is not needed because SetMinSum is not payable.
        vm.prank(address(attacker));
        uint256 oldMinSum = c.MinSum();
        // attacker calls SetMinSum(v1). Inside its fallback, it calls SetMinSum(v2).
        attacker.attack(v1);
        uint256 newMinSum = c.MinSum();
        // In the reference (with locked_ = true), the reentrant call is blocked, so newMinSum == v1.
        // In the buggy version (without locked_ = true), the reentrant call succeeds, so newMinSum == v2.
        // The property: after a call to SetMinSum, the stored MinSum must equal the argument passed to
        // the outermost call, regardless of any reentrant behaviour.
        assertTrue(newMinSum == v1);
    }
}

// Minimal adversarial helper: a re-entrant attacker whose fallback calls back into C.SetMinSum.
