pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 val1, uint256 val2) public {
        // restrict to plausible range
        bound(val1, 1, type(uint256).max - 1);
        bound(val2, 1, type(uint256).max - 1);
        vm.assume(val1 != val2);

        // deploy a re-entrant attacker that calls SetMinSum(val2) during SetLogFile
        ReentrantAttacker attacker = new ReentrantAttacker(c, val2);

        // initialize the contract normally
        c.SetLogFile(address(attacker));
        c.Initialized();
        c.SetMinSum(val1);

        // trigger reentrancy: the attacker's receive() calls SetMinSum(val2) during SetLogFile execution
        (bool okBefore,) = address(c).call(abi.encodeWithSignature("SetLogFile(address)", address(attacker)));
        bool refReentrantReverted = !okBefore;

        // Now read MinSum: with correct nonReentrant, reentrant call must have failed, MinSum stays val1;
        // buggy version allows reentrant call, MinSum could be val2 (or val1 if the reentrant call also succeeds).
        // The invariant: after an initialized contract, any call to SetMinSum that is reentrant must revert,
        // so MinSum remains unchanged. If the reentrant call succeeded, MinSum differs.
        uint256 currentMinSum = c.MinSum();

        // The reference must hold: either the reentrant call reverted (refReentrantReverted true),
        // or MinSum remains val1 (the first non-reentrant value).
        // In the buggy version, reentrant SetMinSum can succeed, changing MinSum to val2, making this false.
        assertTrue(refReentrantReverted || currentMinSum == val1);
    }
}

contract ReentrantAttacker {
    C target;
    uint256 reentrantVal;
    constructor(C _target, uint256 _reentrantVal) {
        target = _target;
        reentrantVal = _reentrantVal;
    }
    fallback() external payable {
        target.SetMinSum(reentrantVal);
    }
}

