pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Reenterer {
    C public target;
    uint256 public val;
    bool public done;
    constructor(C _target, uint256 _val) {
        target = _target;
        val = _val;
    }
    fallback() external payable {
        if (!done) {
            done = true;
            target.SetMinSum(val);
        }
    }
}

contract InvMutTest is Test {
    C c;
    Reenterer re;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(address log, uint256 min1, uint256 min2, uint256 lockTime, uint256 collectAmt) public {
        vm.assume(log != address(0));
        vm.assume(min1 != min2);
        vm.assume(min1 > 0 && min2 > 0);
        vm.assume(lockTime > 0);
        vm.assume(collectAmt > 0);
        vm.assume(collectAmt <= min1 && collectAmt <= min2);

        // Initialize contract
        c.SetLogFile(log);
        c.SetMinSum(min1);
        c.Initialized();

        // Deploy reenterer that will call SetMinSum(min2)
        re = new Reenterer(c, min2);

        // Fund reenterer and make it call Put, triggering fallback->reenter
        vm.deal(address(this), collectAmt + 0.1 ether);
        vm.deal(address(re), collectAmt + 0.1 ether);
        vm.prank(address(re));
        // Put will trigger LogFile.AddMessage which does a low-level call? No, it's a contract call.
        // To trigger reentrancy, we need the fallback to be called during execution.
        // We can use Collect with a call to reenterer that will receive ETH and trigger fallback.
        // But we need reenterer to have a balance in C first.
        vm.prank(address(re));
        c.Put{value: lockTime}(lockTime);

        // Warp past unlock time
        vm.warp(block.timestamp + lockTime + 1);

        // Now Collect from reenterer, sending ETH to reenterer, triggering fallback, which calls SetMinSum(min2)
        uint256 minBefore = c.MinSum();
        try c.Collect(collectAmt) { } catch { }
        uint256 minAfter = c.MinSum();

        // After initialization, a reentrant call to SetMinSum should either revert (leaving MinSum unchanged)
        // or the reentrant call should be blocked and MinSum stays as min1.
        // In the correct version, the nonReentrant modifier prevents reentrant SetMinSum from executing,
        // so MinSum remains min1. In the buggy version, it succeeds, changing MinSum to min2.
        assertTrue(minAfter == min1);
    }
}

