contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockTime1, uint256 lockTime2, uint256 amount1, uint256 amount2, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(lockTime1 <= type(uint256).max - block.timestamp);
        vm.assume(lockTime2 <= type(uint256).max - block.timestamp);
        vm.assume(amount1 <= type(uint256).max - amount2);

        vm.deal(actor, amount1 + amount2);

        vm.prank(actor);
