        vm.prank(actor);
        c.Put{value: amount2}(lockTime2);
        uint256 unlockAfterSecond = c.Acc(actor).unlockTime;

        // After two consecutive Puts, the unlockTime should be at least the max of the two separately computed times.
        // More precisely, it should never be less than unlockAfterFirst.
        // The reference satisfies unlockAfterSecond >= unlockAfterFirst for all inputs,
        // but the buggy version can make unlockAfterSecond less than unlockAfterFirst.
        assertTrue(unlockAfterSecond >= unlockAfterFirst);
    }
}
